template.query:
subscription SubscribeTemplateExecutionStream($templateIdentifier: String!, $variables: JSON, $trackUsage: Boolean = true) {
  executeTemplateStream(
    templateIdentifier: $templateIdentifier
    variables: $variables
    trackUsage: $trackUsage
  ) {
    status
    data
    progress
    metadata {
      templateId
      templateName
      complexityScore
      estimatedTokens
      version
      executionTime
    }
    timestamp
    error
  }
}
